export function useLocalizedUrl(url: string): string {
  const locale = useSelector(languageSelector);

  let hostname: string;
  let origin: string;
  try {
    const parsed = new URL(url);
    hostname = parsed.hostname;
    origin = parsed.origin;
  } catch {
    return url;
  }

  switch (hostname) {
    case "www.ledger.com": {
      const localeCode = WWW_LOCALE_MAP[locale] ?? locale;
      return url.replace(origin, `${origin}/${localeCode}`);
    }
