      const localeCode = SUPPORT_LOCALE_MAP[locale] ?? locale;
      return url.replace("/hc/", `/hc/${localeCode}/`);
    }
    case "shop.ledger.com": {
      const localeCode = SHOP_LOCALE_MAP[locale] ?? locale;
      return url.replace(origin, `${origin}/${localeCode}`);
    }
    default:
      return url;
  }
}
